"use strict";
const DB = JSON.parse(document.getElementById("lnk-data").textContent);
const METHODS = DB.методы || ["ВИК","УЗД","УЗТ","АЭ","ТВ","ТК","ВД","МК"];
// Месяцы объявлены здесь, а не рядом с планом ППР, где были раньше:
// на них ссылается поле «месяц представления на поверку» в карточке
// прибора (REGS ниже), а REGS собирается раньше плана ППР — иначе
// список месяцев в поле оказался бы ещё не созданным.
const МЕСЯЦЫ=["Январь","Февраль","Март","Апрель","Май","Июнь","Июль",
              "Август","Сентябрь","Октябрь","Ноябрь","Декабрь"];
const objById = {}, objByName = {};   // строятся из рабочего справочника O
let curView="journal", query="", ндФильтрМетод="";

// «Живые» записи — без удалённых. Удаление не выкидывает запись, а ставит
// метку z.удалено (надгробие): так удаление можно перенести файлом обмена
// тем же слиянием по свежести. Показываем и считаем только живые.
function liveJ(){ return J.filter(z=>!z.удалено); }
// Метка последнего события записи — правка или удаление, что позже. По ней
// слияние решает, чья версия свежее (в т.ч. «удалено» против «изменено»).
function lastTs(z){ const a=z.изменено||"", b=z.удалено||""; return a>b?a:b; }

// ── Номера протоколов и актов ─────────────────────────────
// Счётчик не хранится отдельно: следующий номер — это «максимум из уже
// выданных + 1». Так счётчик не может разойтись с данными и не требует
// отдельной синхронизации при обмене — журналы сливаются, и множество
// занятых номеров сливается вместе с ними.
//
// Считаем по ВСЕМ записям, включая удалённые и аннулированные: номер
// повторно не используется, дыра от аннулированной записи остаётся
// навсегда (правило заказчика).
function годЗаписи(z){ return (z.дата||"").slice(0,4); }
function номерМетода(z,м){ const v=(z.методы||{})[м]; return v?String(v.н||"").trim():""; }
function следующийПротокол(метод, год){
  let max=0;
  J.forEach(z=>{ if(годЗаписи(z)!==String(год)) return;
    const н=номерМетода(z,метод);
    if(/^\d+$/.test(н)) max=Math.max(max, +н); });
  return max+1;
}
function следующийАкт(год){
  let max=0;
  J.forEach(z=>{ if(годЗаписи(z)!==String(год)) return;
    const m=/^АКТ\s+(\d+)-(\d{4})$/.exec(String(z.акт||"").trim());
    if(m && m[2]===String(год)) max=Math.max(max, +m[1]); });
  return max+1;
}
function дваЗнака(n){ return n<10 ? "0"+n : String(n); }
// Полное обозначение протокола: 01-2026-ТК. Идёт в поле #Номер документа.
function обозначениеПротокола(z,м){
  const н=номерМетода(z,м), г=годЗаписи(z);
  return (/^\d+$/.test(н) && г) ? дваЗнака(+н)+"-"+г+"-"+м : "";
}
function методыБезНомера(z){ return methodsOf(z).filter(м=>!/^\d+$/.test(номерМетода(z,м))); }
function ждётНомеров(z){ return methodsOf(z).length>0 && методыБезНомера(z).length>0; }

// ── Право выдачи номеров (эстафета) ───────────────────────
// Право в каждый момент у одного места. Оно лежит в общих данных и
// ходит с обменом: два места не выдадут один номер, потому что выдавать
// может только держатель. Приём тот же, что у «роли мастера».
const GRANT_KEY="lnk_grant";
function getGrant(){
  try{ const r=ХР.getItem(GRANT_KEY); if(r){ const o=JSON.parse(r);
        return {место:o.место||"", изменено:o.изменено||""}; } }catch(e){}
  return {место:"", изменено:""};
}
function saveGrant(g){ try{ ХР.setItem(GRANT_KEY, JSON.stringify(g)); }catch(e){} }
function правоМоё(){ const g=getGrant(); return !!g.место && g.место===getWS().код; }
function правоСвободно(){ return !getGrant().место; }

// ── Рабочий журнал (правки живут в localStorage поверх вшитых данных) ──
// Данные вшиты в файл, поэтому редактируемая копия журнала хранится в
// памяти браузера. КЛЮЧ НЕ ЗАВИСИТ ОТ ВЕРСИИ ПРОГРАММЫ — иначе новая
// версия смотрела бы в другой «ящик» и открывалась пустой. Браузер держит
// память для file:// независимо от конкретного файла, поэтому обновление
// программы (замена файла) ваши записи сохраняет.
const STORE_KEY = "lnk_journal";
let J;
function loadJournal(){
  try{
    let raw = ХР.getItem(STORE_KEY);
    if(!raw){                                   // перенос со старого ключа с версией (до 3.1)
      for(let i=0;i<ХР.length;i++){
        const k=ХР.key(i);
        if(k && k.indexOf("lnk_journal_")===0){ raw=ХР.getItem(k); break; }
      }
    }
    if(raw){ const p=JSON.parse(raw); const rows=Array.isArray(p)?p:p.rows;
             if(Array.isArray(rows)) return rows; }
  }catch(e){}
  return JSON.parse(JSON.stringify(DB.журнал));   // первый запуск — копия вшитых
}
// Разовая чистка переноса: в 22 записях в «№ акта» лежал номер протокола
// вида 01-2026-ТК. Он и так стоит в колонке своего метода, а по правилу
// заказчика для ТК и ВД акт не оформляется — значит поле просто лишнее.
function починитьАкты(){
  let n=0;
  J.forEach(z=>{ if(/^\d+-\d{4}-[А-Я]{2}$/.test(String(z.акт||"").trim())){ z.акт=""; n++; } });
  if(n) saveJournal();
  return n;
}
function saveJournal(){
  проставитьБазу(STORE_KEY, J);
  записатьИсторию(STORE_KEY, J);
  try{ ХР.setItem(STORE_KEY, JSON.stringify({baseVersion:DB.версия, сохранено:new Date().toISOString(), rows:J})); }
  catch(e){ переполнение(e); }
  снятьСнимок(STORE_KEY, J);
  setChrome();
  копияПоСлучаю();
}
// Отказ записи — не мелочь на полсекунды: правка НЕ сохранена. Молчать
// об этом нельзя, поэтому не подсказка внизу экрана, а окно с ответом,
// что делать.
function переполнение(e){
  const квота = e && (e.name==="QuotaExceededError" || e.code===22);
  if(квота) alert("ПАМЯТЬ БРАУЗЕРА ЗАПОЛНЕНА — правка не сохранена.\n\n"+
    "Что сделать сейчас:\n"+
    "1. «Обмен» → «Сохранить копию» (файл уйдёт в папку загрузок).\n"+
    "2. Удалите из журнала то, что уже сдано в архив, либо сообщите мне.\n"+
    "(Программа работает в старом хранилище с пределом 5 МБ, потому что "+
    "IndexedDB в этом браузере недоступна"+(ХР.причина()?": "+ХР.причина():"")+".)\n\n"+
    "Пока память не освободится, новые правки сохраняться не будут.");
  else toast("Не удалось сохранить в память браузера");
}
// ── Рабочее место (код для обмена) ────────────────────────
// Код места входит в id новых записей — тогда при слиянии журналов
// с разных мест записи не сталкиваются (у каждого места свои id).
function getWS(){
  try{ const r=ХР.getItem("lnk_ws"); if(r){ const o=JSON.parse(r);
        return {код:(o.код||"М1"), мастер:!!o.мастер, начальник:!!o.начальник}; } }catch(e){}
  return {код:"М1", мастер:false, начальник:false};
}
function saveWS(o){
  try{ ХР.setItem("lnk_ws", JSON.stringify(o)); }catch(e){}
  const el=document.getElementById("wsName"); if(el) el.textContent=o.код;
}
function newId(pfx){
  return (pfx||"З") + "-" + getWS().код + "-" + Date.now().toString(36).toUpperCase()
    + "-" + Math.random().toString(36).slice(2,5).toUpperCase();
}

// ── Справочники как рабочие копии (для правки и обмена) ────
// Объекты, приборы, специалисты — тоже редактируемые и переносятся
// обменом, поэтому живут в памяти браузера, как журнал. Те же правила:
// «живые» без удалённых, слияние по свежести, мягкое удаление.
const REG_OBJ="lnk_obj", REG_SI="lnk_si", REG_PPL="lnk_ppl";
// Акт охватывает много записей журнала (в вашем акте 28-2026 — 23 объекта),
// поэтому у него есть свои поля: контракт, фраза об объектах, подписи.
// В записи журнала их держать негде — они общие на весь акт.
const REG_AKT="lnk_akts";
// Заказывающее подразделение — своя карточка: у каждого свой тип контракта,
// свои реквизиты на каждый год и свой подписант со стороны экспертной
// организации. Держать это в записи журнала нельзя — повторялось бы в
// сотнях строк и разъезжалось.
const REG_ПОДР="lnk_podr";
// Падеж объекта. Склонять автоматически ненадёжно, а вписывать фразу
// заново в каждом акте — работа впустую: наименования повторяются.
// Поэтому форма запоминается ЗА НАИМЕНОВАНИЕМ и дальше подставляется
// сама во все акты. В журнале 315 записей, но уникальных наименований
// 127, а два десятка самых частых покрывают две трети записей — то есть
// это разовая работа, а не постоянная.
const REG_ПАДЕЖ="lnk_padezh";
// Разделы 9 и 10 паспорта ЛНК (СДАНК-01-2020, Приложение 3) — по вашему
// бланку паспорта: перечень нормативных документов и сведения о
// помещениях. Раньше в паспорте были только честные пометки «данных
// нет» — теперь свои справочники, как у объектов и приборов.
const REG_НД="lnk_nd", REG_ПОМ="lnk_pom";
