function live(arr){ return arr.filter(z=>!z.удалено); }
// Сравнение идентификаторов ТОЛЬКО через строку. У записей из книги
// (данные.json: приборы, объекты, специалисты) id — ЧИСЛО, а всякая
// сохранённая ссылка на карточку приходит из <select>.value, то есть
// всегда строка: строгое `===` их не равняет, и связь молча считается
// несуществующей. На этом уже поймана потеря ссылки «неотъемлемая часть
// прибора» — см. запись в CLAUDE.md.
function тотЖеИд(a,b){ return String(a)===String(b); }
function найтиПоИд(arr,ид){ return (arr||[]).find(x=>тотЖеИд(x.id,ид))||null; }

// ── Строка объекта → карточка ─────────────────────────────
// В журнале объект — строка «наименование, зав. № …, рег. № …». Карточку
// искать только по наименованию и заводскому номеру было нельзя: у
// однотипных аппаратов («теплообменник 273ТНГ» — 12 карточек, рег. № 79…90)
// заводского номера нет вовсе, различает их РЕГИСТРАЦИОННЫЙ номер. Прежний
// поиск (имя + зав.) на таких отдавал одну и ту же карточку всем — 12
// записей журнала оказались привязаны не к своему аппарату. Здесь сужаю по
// наименованию, затем по заводскому, затем по регистрационному номеру —
// каждый шаг только если он что-то оставляет.
function разобратьСтрокуОбъекта(строка){
  строка=String(строка||"");
  const мЗав=/зав\.?\s*№\s*([^,;]+)/i.exec(строка), мРег=/рег\.?\s*№\s*([^,;]+)/i.exec(строка);
  return { имя:строка.replace(/,?\s*(зав|рег)\.?\s*№.*$/i,"").trim(),
           зав:мЗав?мЗав[1].trim():"", рег:мРег?мРег[1].trim():"" };
}
function карточкаПоСтроке(строка, зав, рег){
  const р=разобратьСтрокуОбъекта(строка);
  const з=String(зав||р.зав||"").trim(), г=String(рег||р.рег||"").trim();
  let c=live(O).filter(o=>String(o.наименование||"").trim()===р.имя);
  if(!c.length) return objByName[р.имя]||objByName[String(строка||"").trim()]||null;
  const сузить=(поле,v)=>{ const f=c.filter(o=>String(o[поле]||"").trim()===v); if(f.length) c=f; };
  if(з) сузить("зав",з); else сузить("зав","");
  if(г) сузить("рег",г);
  return c[0];
}
// Записи, привязанные прежним поиском не к той карточке: в строке записи
// стоит свой зав./рег. номер, а у карточки — другой, при том что карточка
// с верным номером есть. Перепривязываю при загрузке, без отметки
// «изменено»: правка однозначна и делается на каждом месте одинаково.
function перепривязатьОбъекты(){
  let n=0;
  J.forEach(z=>{
    if(z.удалено || !z.объект) return;
    const р=разобратьСтрокуОбъекта(z.объект);
    const з=String(z.зав||р.зав||"").trim(), г=String(z.рег||р.рег||"").trim();
    if(!з && !г) return;
    const тек=найтиПоИд(O,z.объект_ид);
    if(тек && (!з || String(тек.зав||"").trim()===з) && (!г || String(тек.рег||"").trim()===г)) return;
    const нов=карточкаПоСтроке(z.объект, з, г);
    if(!нов || (тек && тотЖеИд(нов.id,тек.id))) return;
    if((з && String(нов.зав||"").trim()!==з) || (г && String(нов.рег||"").trim()!==г)) return;  // верной карточки нет — не гадаю
    z.объект_ид=нов.id; n++;
  });
  return n;
}
function rebuildObjIndex(){
  for(const k in objById) delete objById[k];
  for(const k in objByName) delete objByName[k];
  live(O).forEach(o=>{ objById[o.id]=o; if(o.наименование) objByName[o.наименование]=o; });
}
// ── Записи, подставленные программой (сид), и их id ────────
// Объекты и приборы приходят из данные.json с готовыми id — они
// одинаковы на ВСЕХ рабочих местах, поэтому обмен сливает их по id без
// задвоения. А норм. документы и помещения вшиты литералами в шаблон
// БЕЗ id, и раньше id достраивался локальным newId() — тот включает код
// места и время, значит у одного и того же документа на М1 и М2 выходили
// РАЗНЫЕ id. Последствия было бы два, оба скверные: обмен добавил бы
// второй экземпляр всех 134 документов вместо слияния, а набор норм.
// документов в «Методиках контроля» (он хранит id) на другом месте вёл
// бы в пустоту. Поэтому id сидированных записей теперь вычисляется из
// позиции в самом сиде — он одинаков везде.
function сидId(pfx, i){ return pfx+"-С-"+String(i+1).padStart(3,"0"); }
// Признак, по которому запись узнаётся независимо от id. Взят не с
// потолка: это ровно те поля, по которым «Проверка данных» уже считает
// карточки дублями — обозначение с наименованием у документа,
// идентификация у помещения.
function ключНД(x){ return String(x.обозначение||"").trim().toLowerCase()+"|"+
                           String(x.наименование||"").trim().toLowerCase(); }
function ключПОМ(x){ return String(x.идентификация||"").trim().toLowerCase(); }
// Перевод уже сохранённых записей на канонические id. У заказчика
// справочник давно заполнен, локальные id проставлены — просто сменить
// схему мало, надо переименовать существующие и починить ссылки на них.
function каноническиеId(массив, сид, pfx, ключФн){
  const замены={};
  const занято={}; массив.forEach(x=>{ if(x.id) занято[x.id]=1; });
  сид.forEach((э,i)=>{
    const канон=сидId(pfx,i), к=ключФн(э);
    if(!к || к==="|") return;
    const есть=массив.find(x=>ключФн(x)===к);
    if(!есть || есть.id===канон) return;
    if(занято[канон]) return;           // канонический id уже занят другой карточкой — не трогаем
    замены[есть.id]=канон; delete занято[есть.id];
    есть.id=канон; занято[канон]=1;
  });
  return замены;
}
// Ссылки на норм. документы живут в двух местах: стандартный набор
// метода («Методики контроля») и переопределение набора в самой записи
// журнала. Обе надо перевести на новые id вместе с самими карточками,
// иначе отмеченные документы молча пропадут из набора.
function заменитьСсылкиНД(замены){
  const ключи=Object.keys(замены); if(!ключи.length) return;
  const мт=getМетодики(); let мтИзменилось=false;
  METHODS.forEach(м=>{
    const сп=(мт[м]||{}).нд||[];
    const нов=сп.map(id=>замены[id]||id);
    if(нов.join("\u0001")!==сп.join("\u0001")){ мт[м].нд=нов; мтИзменилось=true; }
  });
  if(мтИзменилось) saveМетодики(мт, true);   // починка ссылок, не правка человека
  let журналИзменился=false;
  J.forEach(z=>Object.keys(z.методы||{}).forEach(м=>{
    const сп=(z.методы[м]||{}).нд; if(!Array.isArray(сп)) return;
    const нов=сп.map(id=>замены[id]||id);
    if(нов.join("\u0001")!==сп.join("\u0001")){ z.методы[м].нд=нов; журналИзменился=true; }
  }));
  if(журналИзменился) saveJournal();
}
// Общее слияние по id со свежестью (журнал и справочники одинаково).
function mergeInto(arr, key, incoming){
  let added=0, updated=0, skipped=0; const idx={}; arr.forEach((z,i)=>idx[z.id]=i);
  (incoming||[]).forEach(r=>{ if(!r || r.id==null || r.id==="") return;
    if(idx[r.id]==null){ arr.push(r); idx[r.id]=arr.length-1; if(!r.удалено) added++; }
    else { if(конфликтПравок(key,arr[idx[r.id]],r)) записатьКонфликт(key,arr[idx[r.id]],r);
      if(lastTs(r) > lastTs(arr[idx[r.id]])){ arr[idx[r.id]]=r; updated++; } else skipped++; } });
  if(key && (added||updated)) saveReg(key, arr);
  return {added,updated,skipped};
}
// Слияние справочника, где одну и ту же карточку могли завести руками на
// разных местах — тогда id у неё разные, и обычное слияние по id дало бы
// два экземпляра одного ГОСТа. Поэтому у не найденной по id записи
// пробуем ещё естественный ключ (обозначение документа, идентификация
// помещения). Свой id при обновлении СОХРАНЯЕТСЯ: на него ссылаются
// наборы норм. документов в методиках и в записях журнала.
function mergeСправочник(arr, key, incoming, ключФн){
  let added=0, updated=0, skipped=0;
  const поId={}, поКлючу={};
  arr.forEach((z,i)=>{ поId[z.id]=i; const к=ключФн(z); if(к && к!=="|") поКлючу[к]=i; });
  (incoming||[]).forEach(r=>{
    if(!r || r.id==null || r.id==="") return;
    let i=поId[r.id];
    if(i==null){ const к=ключФн(r); if(к && к!=="|" && поКлючу[к]!=null) i=поКлючу[к]; }
    if(i==null){
      arr.push(r); поId[r.id]=arr.length-1;
      const к=ключФн(r); if(к && к!=="|") поКлючу[к]=arr.length-1;
      if(!r.удалено) added++;
    } else {
      if(конфликтПравок(key,arr[i],r)) записатьКонфликт(key,arr[i],r);
      if(lastTs(r) > lastTs(arr[i])){ arr[i]=Object.assign({}, r, {id:arr[i].id}); updated++; }
      else skipped++;
    }
  });
  if(key && (added||updated)) saveReg(key, arr);
  return {added,updated,skipped};
}

// Отдать файл на скачивание (обмен, копии).
function dl(name, text){
  const blob=new Blob([text],{type:"application/json;charset=utf-8"}), url=URL.createObjectURL(blob);
  const a=document.createElement("a"); a.href=url; a.download=name;
  document.body.appendChild(a); a.click();
  setTimeout(()=>{URL.revokeObjectURL(url); a.remove();}, 400);
}

